(()=>{'use strict';
 const $=id=>document.getElementById(id);
 const save=document.createElement('button');save.id='itop-proposal-save';save.type='button';save.textContent='SALVAR';$('itop-flow-finish').after(save);
 save.onclick=async()=>{if(save.disabled)return;save.disabled=true;const status=$('pdfStatus');status.textContent='Salvando proposta…';try{if(!window.ITOPSalesFlow?.canSave())throw Error('Aguarde a conclusão da operação atual');const r=await window.ITOPProposalSave();status.textContent='Proposta salva com sucesso. Identificação: '+r.id;}catch(e){status.textContent='Não foi possível salvar: '+e.message+'. Os dados continuam preenchidos para nova tentativa.';}finally{save.disabled=false;}};
 const actions=document.querySelector('#energia .energy-final .actions');
 if(actions){const status=$('itopEnergyActionStatus');if(status)actions.after(status);actions.replaceChildren();for(const [id,label,target] of [['energy-review','REVISAR FECHAMENTO','fechamento'],['energy-back','VOLTAR AOS SERVIÇOS','pacote'],['energy-create-pdf','CRIAR PDF',null]]){const b=document.createElement('button');b.type='button';b.id=id;b.textContent=label;b.onclick=()=>{if(target)return window.switchModule(target);try{const p=window.ITOPProposalPDF.create(window.ITOPCommercialBridge.snapshot(),{energyOnly:true});p.doc.save(p.name);$('itopEnergyActionStatus').textContent='PDF da simulação atual gerado.';}catch(e){$('itopEnergyActionStatus').textContent=e.message;}};actions.append(b);}}
 document.querySelectorAll('#sondagem input,#sondagem select,#pacote input,#pacote select,#energia input,#energia select').forEach(el=>el.autocomplete='off');
 function resetPDF(){for(const id of ['pdf-review-dialog','shareDialog']){const d=$(id);if(d?.open)d.close();}const frame=$('pdf-review-frame');if(frame)frame.src='about:blank';for(const id of ['pdfStatus','shareStatus','itopEnergyActionStatus'])if($(id))$(id).textContent='';for(const id of ['includeEnergy','includeEnergyFromEnergy'])if($(id))$(id).checked=false;}
 window.addEventListener('itop:proposal-loaded',e=>{if(!e.detail?.id){resetPDF();$('survey-result').dispatchEvent(new Event('input',{bubbles:true}));recalc();}});
})();
